def _set_for(book_data: list[tuple[int, int, str, str, str]], lang: str, book_name: str) -> dict:
    """Group authored entries by chapter for one language. Adds an
    optional `context` field when SECTION_CONTEXTS has a matching entry."""
    out: dict[str, list[dict]] = {}
    for ch, vs, simp, trad, en in book_data:
        title = {"hans": simp, "hant": trad, "en": en}[lang]
        item: dict = {"verse": vs, "title": title}
        ctx = SECTION_CONTEXTS.get((book_name, ch, vs))
        if ctx is not None:
            ctx_text = {"hans": ctx[0], "hant": ctx[1], "en": ctx[2]}[lang]
            item["context"] = ctx_text
        out.setdefault(str(ch), []).append(item)
    # Sort each chapter's entries by verse for deterministic output.
    for ch in out:
        out[ch].sort(key=lambda e: e["verse"])
    return out


def main() -> int:
    books_data = {
        # Pentateuch
        "Genesis": GENESIS,
        "Exodus": EXODUS,
        "Leviticus": LEVITICUS,
        "Numbers": NUMBERS,
        "Deuteronomy": DEUTERONOMY,
        # OT history
        "Joshua": JOSHUA,
        "Judges": JUDGES,
        "Ruth": RUTH,
        "1 Samuel": FIRST_SAMUEL,
        "2 Samuel": SECOND_SAMUEL,
        "1 Kings": FIRST_KINGS,
        "2 Kings": SECOND_KINGS,
        "1 Chronicles": FIRST_CHRONICLES,
        "2 Chronicles": SECOND_CHRONICLES,
        "Ezra": EZRA,
        "Nehemiah": NEHEMIAH,
        "Esther": ESTHER,
        # Wisdom
        "Job": JOB,
        "Psalms": PSALMS,
        "Proverbs": PROVERBS,
        "Ecclesiastes": ECCLESIASTES,
        "Song of Solomon": SONG_OF_SOLOMON,
        # Major prophets
        "Isaiah": ISAIAH,
        "Jeremiah": JEREMIAH,
        "Lamentations": LAMENTATIONS,
        "Ezekiel": EZEKIEL,
        "Daniel": DANIEL,
        # Minor prophets
        "Hosea": HOSEA,
        "Joel": JOEL,
        "Amos": AMOS,
        "Obadiah": OBADIAH,
        "Jonah": JONAH,
        "Micah": MICAH,
        "Nahum": NAHUM,
        "Habakkuk": HABAKKUK,
        "Zephaniah": ZEPHANIAH,
        "Haggai": HAGGAI,
        "Zechariah": ZECHARIAH,
        "Malachi": MALACHI,
        # Gospels + Acts
        "Matthew": MATTHEW,
        "Mark": MARK,
        "Luke": LUKE,
        "John": JOHN,
        "Acts": ACTS,
        # Pauline letters
        "Romans": ROMANS,
        "1 Corinthians": FIRST_CORINTHIANS,
        "2 Corinthians": SECOND_CORINTHIANS,
        "Galatians": GALATIANS,
        "Ephesians": EPHESIANS,
        "Philippians": PHILIPPIANS,
        "Colossians": COLOSSIANS,
        "1 Thessalonians": FIRST_THESSALONIANS,
        "2 Thessalonians": SECOND_THESSALONIANS,
        "1 Timothy": FIRST_TIMOTHY,
        "2 Timothy": SECOND_TIMOTHY,
        "Titus": TITUS,
        "Philemon": PHILEMON_BOOK,
        # General + Revelation
        "Hebrews": HEBREWS,
        "James": JAMES,
        "1 Peter": FIRST_PETER,
        "2 Peter": SECOND_PETER,
        "1 John": FIRST_JOHN,
        "2 John": SECOND_JOHN,
        "3 John": THIRD_JOHN,
        "Jude": JUDE,
        "Revelation": REVELATION,
    }

    payload = {
        "_meta": {
            "version": 1,
            "books": list(books_data.keys()),
            "generatedAt": _dt.datetime.now(_dt.timezone.utc).strftime(
                "%Y-%m-%dT%H:%M:%SZ"
            ),
            "description": (
                "Section / paragraph titles. Loaded by SectionTitleService and "
                "rendered above the matched verse in the reading pane. Three "
                "title sets in this Phase-1 file: cuv (simplified), cuv-tr "
                "(traditional), english-classic (English). The version-to-set "
                "mapping lives in lib/constants/section_title_map.dart."
            ),
        },
        "sets": {
            "cuv": {b: _set_for(d, "hans", b) for b, d in books_data.items()},
            "cuv-tr": {b: _set_for(d, "hant", b) for b, d in books_data.items()},
            "english-classic": {b: _set_for(d, "en", b) for b, d in books_data.items()},
        },
    }

    with open(OUT, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)
        fh.write("\n")

    total = sum(len(d) for d in books_data.values())
    print(
        f"Wrote {total} titles × 3 languages → "
        f"{OUT} ({os.path.getsize(OUT)} bytes)"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
